from __future__ import annotations

import base64
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
BACKUP_SUFFIX = f".bak_netlify_{datetime.now().strftime('%Y%m%d_%H%M%S')}"

ARQUIVOS = {
    "frontend/src/app/admin/page.tsx": '',
}


def salvar_arquivo(relativo: str, conteudo_b64: str) -> None:
    destino = ROOT / relativo
    destino.parent.mkdir(parents=True, exist_ok=True)

    if destino.exists():
        backup = destino.with_name(destino.name + BACKUP_SUFFIX)
        backup.write_bytes(destino.read_bytes())
        print(f"Backup: {backup}")

    destino.write_bytes(base64.b64decode(conteudo_b64))
    print(f"Atualizado: {destino}")


def main() -> None:
    if not (ROOT / "frontend" / "src" / "app" / "admin").exists():
        raise SystemExit(
            "Coloque instalar_elenco_completo.py na raiz do projeto central-do-galo."
        )

    for relativo, conteudo_b64 in ARQUIVOS.items():
        salvar_arquivo(relativo, conteudo_b64)

    print()
    print("Correção do build do Netlify aplicada.")
    print("- número nulo do Técnico tratado corretamente na ordenação do Admin")
    print()
    print("Agora teste localmente:")
    print(r'cd frontend')
    print(r'npm run build')


if __name__ == "__main__":
    main()
